// Generated data -- see reference/openconnect/README.md (snap section) for
// how to regenerate. Full 3D triangle meshes of the openGrid Snap body
// (mitufy/opengrid-projects opengrid_parametric_snap.scad, generate_snap =
// "openConnect", generate_screw = "None", default openConnect-head/nub/cut/
// notch settings), one per (boardType x snapBodyShape) combination. boardType
// "Heavy" has no upstream-supported snap_thickness and is intentionally not
// baked -- see openGridSnapGeometry.ts.
//
// Local frame is OpenSCAD's own (Z-up, snap_thickness spanning
// [0, snap_thickness] then the openConnect head extending further +Z);
// openGridSnapGeometry.ts applies the same rotateX(-90deg) used elsewhere in
// this codebase to map that onto the app's Y-up scene convention.
//
// Rendered via openscad/openscad:dev (nightly) + a BOSL2 checkout, one
// variant at a time:
//   openscad -D 'snap_thickness=<6.8|4>' -D 'snap_body_shape="<Directional|Symmetric>"' \
//     -D 'generate_snap="openConnect"' -D 'generate_screw="None"' \
//     --export-format asciistl -o out.stl opengrid_parametric_snap.scad
//
// Each raw render reported NoError/single-manifold-volume from OpenSCAD's own
// CGAL check, but cleaning it up for use here took 2 passes:
//   1. The two Full-thickness (snap_thickness=6.8) variants each contained 4
//      zero-area triangles (a repeated vertex index within one triangle) at
//      the uninstall notch's tangent point -- dropped (identified by exact
//      repeated-vertex-index after vertex welding). The Lite variants had
//      none of these.
//   2. ALL 4 variants (Full and Lite alike) contained ~20-32 pairs of
//      vertices sitting only ~1e-8..1e-7mm apart -- CGAL/STL-export float
//      noise for what's meant to be a single coincident point (confirmed via
//      nearest-neighbor search), not a designed micro-gap. trimesh's default
//      STL-load vertex merge left these as separate vertices (each half of a
//      pair stays independently well-formed, so a plain open/non-manifold
//      edge count still reports clean) -- but reproducing this codebase's
//      own analyzeTriangleSoup check (which re-derives topology by spatial
//      quantization, coarser than that ~1e-8 gap) collapses each pair into
//      one vertex, which then merges 2 unrelated real edges into a single
//      edge key and reports it non-manifold (edge count 4, not 2) -- a false
//      positive from re-deriving topology at production precision, not an
//      actual defect (trimesh confirms 0 open / 0 non-manifold on the
//      untouched float64 mesh either way). Explicitly welded these pairs
//      (trimesh merge_vertices(digits_vertex=6) -- well above the ~1e-8
//      noise floor, well below any real feature size), which also exposed a
//      further ~10-16 newly-degenerate triangles per variant (two of a
//      triangle's three corners collapsing into the same welded vertex);
//      dropped those too, in the same way as step 1.
// All 4 variants confirmed watertight (0 open edges, 0 non-manifold edges)
// after both cleanup passes, verified both directly (full float64 precision)
// and via analyzeTriangleSoup's own quantization-based algorithm reproduced
// against this file's actual rounded/rotated output.
